CREATE TABLE game_metadata(singleton INTEGER PRIMARY KEY CHECK(singleton=1),schema_version INTEGER NOT NULL CHECK(schema_version>0),last_observed_ms INTEGER NOT NULL CHECK(last_observed_ms BETWEEN 0 AND 9007199254740991),command_floor_ms INTEGER NOT NULL CHECK(command_floor_ms BETWEEN 0 AND 9007199254740991)) STRICT;
CREATE TABLE game_record(singleton INTEGER PRIMARY KEY CHECK(singleton=1),game_id TEXT NOT NULL UNIQUE,creator_id TEXT NOT NULL,creation_command TEXT NOT NULL,fingerprint BLOB NOT NULL CHECK(length(fingerprint)=32),host_id TEXT NOT NULL,host_assignment_revision INTEGER NOT NULL CHECK(host_assignment_revision BETWEEN 0 AND 9007199254740991),state TEXT NOT NULL CHECK(state IN ('new','awaiting_players','in_progress','cancelled')),revision INTEGER NOT NULL CHECK(revision BETWEEN 0 AND 9007199254740991),created_at INTEGER NOT NULL CHECK(created_at BETWEEN 0 AND 9007199254740991),last_host_activity INTEGER NOT NULL CHECK(last_host_activity BETWEEN 0 AND 9007199254740991),idle_due INTEGER CHECK(idle_due IS NULL OR idle_due BETWEEN 0 AND 9007199254740991),lobby_opened_at INTEGER CHECK(lobby_opened_at IS NULL OR lobby_opened_at BETWEEN 0 AND 9007199254740991),started_at INTEGER CHECK(started_at IS NULL OR started_at BETWEEN 0 AND 9007199254740991),ended_at INTEGER CHECK(ended_at IS NULL OR ended_at BETWEEN 0 AND 9007199254740991),game_code TEXT,published_at INTEGER CHECK(published_at IS NULL OR published_at BETWEEN 0 AND 9007199254740991),cancellation_reason TEXT) STRICT;
CREATE TABLE game_configuration(singleton INTEGER PRIMARY KEY CHECK(singleton=1) REFERENCES game_record(singleton),numeric_upper_bound INTEGER NOT NULL CHECK(numeric_upper_bound BETWEEN 1 AND 1000),board_side_length INTEGER NOT NULL CHECK(board_side_length BETWEEN 2 AND 10),free_cells_enabled INTEGER NOT NULL CHECK(free_cells_enabled IN (0,1)),player_capacity INTEGER NOT NULL CHECK(player_capacity BETWEEN 2 AND 20),spectator_capacity INTEGER NOT NULL CHECK(spectator_capacity BETWEEN 0 AND 50),winning_pattern TEXT NOT NULL) STRICT;
CREATE TABLE game_free_cells(row INTEGER NOT NULL CHECK(row BETWEEN 1 AND 10),column INTEGER NOT NULL CHECK(column BETWEEN 1 AND 10),PRIMARY KEY(row,column)) STRICT;
CREATE TABLE game_players(player_id TEXT PRIMARY KEY,alias TEXT NOT NULL COLLATE BINARY UNIQUE CHECK(length(CAST(alias AS BLOB)) BETWEEN 1 AND 20),joined_at INTEGER NOT NULL CHECK(joined_at BETWEEN 0 AND 9007199254740991),session_epoch INTEGER NOT NULL CHECK(session_epoch BETWEEN 0 AND 9007199254740991),last_explicit_leave_at INTEGER CHECK(last_explicit_leave_at IS NULL OR last_explicit_leave_at BETWEEN 0 AND 9007199254740991)) STRICT;
CREATE TABLE game_recovery(player_id TEXT PRIMARY KEY REFERENCES game_players(player_id),answer_verifier TEXT NOT NULL CHECK(length(answer_verifier)<=256),normalization_version INTEGER NOT NULL CHECK(normalization_version=1),updated_at INTEGER NOT NULL CHECK(updated_at BETWEEN 0 AND 9007199254740991)) STRICT;
CREATE TABLE game_sessions(session_id TEXT PRIMARY KEY,token_verifier BLOB NOT NULL UNIQUE CHECK(length(token_verifier)=32),game_id TEXT NOT NULL,game_code TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES game_players(player_id),session_epoch INTEGER NOT NULL CHECK(session_epoch>=0),access TEXT NOT NULL,issued_at INTEGER NOT NULL CHECK(issued_at BETWEEN 0 AND 9007199254740991),expires_at INTEGER NOT NULL CHECK(expires_at BETWEEN 0 AND 9007199254740991 AND expires_at>issued_at),revoked_at INTEGER CHECK(revoked_at IS NULL OR revoked_at BETWEEN 0 AND 9007199254740991)) STRICT;
CREATE TABLE game_boards(player_id TEXT PRIMARY KEY REFERENCES game_players(player_id),side_length INTEGER NOT NULL CHECK(side_length BETWEEN 2 AND 10),assigned_at INTEGER NOT NULL CHECK(assigned_at BETWEEN 0 AND 9007199254740991),evaluated_through_call INTEGER NOT NULL CHECK(evaluated_through_call=0)) STRICT;
CREATE TABLE game_board_cells(player_id TEXT NOT NULL REFERENCES game_boards(player_id),row INTEGER NOT NULL,column INTEGER NOT NULL,kind TEXT NOT NULL,value TEXT,is_matched INTEGER NOT NULL CHECK(is_matched IN (0,1)),PRIMARY KEY(player_id,row,column)) STRICT;
CREATE TABLE game_completed_lines(player_id TEXT NOT NULL REFERENCES game_boards(player_id),sequence INTEGER NOT NULL CHECK(sequence>=0),kind TEXT NOT NULL,line_index INTEGER,PRIMARY KEY(player_id,sequence)) STRICT;
CREATE TABLE game_view_revisions(view_key TEXT PRIMARY KEY,revision INTEGER NOT NULL CHECK(revision BETWEEN 0 AND 9007199254740991)) STRICT;
CREATE TABLE game_current_connections(viewer_kind TEXT NOT NULL,session_id TEXT NOT NULL,principal_id TEXT NOT NULL,connection_id TEXT NOT NULL UNIQUE,epoch INTEGER NOT NULL CHECK(epoch BETWEEN 0 AND 9007199254740991),expires_at INTEGER NOT NULL CHECK(expires_at BETWEEN 0 AND 9007199254740991),PRIMARY KEY(viewer_kind,session_id)) STRICT;
CREATE TABLE game_connection_grants(grant_id TEXT PRIMARY KEY,viewer_kind TEXT NOT NULL,session_id TEXT NOT NULL,principal_id TEXT NOT NULL,connection_id TEXT,epoch INTEGER NOT NULL CHECK(epoch BETWEEN 0 AND 9007199254740991),entered_at INTEGER NOT NULL CHECK(entered_at BETWEEN 0 AND 9007199254740991),expires_at INTEGER NOT NULL CHECK(expires_at BETWEEN 0 AND 9007199254740991),UNIQUE(viewer_kind,session_id,connection_id)) STRICT;
CREATE TABLE game_receipts(actor TEXT NOT NULL,command_id TEXT NOT NULL,fingerprint BLOB NOT NULL CHECK(length(fingerprint)=32),outcome TEXT NOT NULL CHECK(length(CAST(outcome AS BLOB))<=4096),completed_at INTEGER NOT NULL CHECK(completed_at BETWEEN 0 AND 9007199254740991),expires_at INTEGER NOT NULL CHECK(expires_at BETWEEN 0 AND 9007199254740991),PRIMARY KEY(actor,command_id)) STRICT;
CREATE TABLE game_pending_work(operation_id TEXT PRIMARY KEY,kind TEXT NOT NULL,phase TEXT NOT NULL,actor TEXT NOT NULL,command_id TEXT NOT NULL,fingerprint BLOB NOT NULL CHECK(length(fingerprint)=32),expected_revision INTEGER NOT NULL CHECK(expected_revision BETWEEN 0 AND 9007199254740991),fence_revision INTEGER NOT NULL CHECK(fence_revision BETWEEN 0 AND 9007199254740991),created_at INTEGER NOT NULL CHECK(created_at BETWEEN 0 AND 9007199254740991),next_attempt_at INTEGER NOT NULL CHECK(next_attempt_at BETWEEN 0 AND 9007199254740991),attempt_count INTEGER NOT NULL CHECK(attempt_count BETWEEN 0 AND 4294967295),UNIQUE(actor,command_id)) STRICT;
CREATE TABLE game_admission_contexts(player_id TEXT PRIMARY KEY,token_verifier BLOB NOT NULL UNIQUE CHECK(length(token_verifier)=32),game_code TEXT NOT NULL,issued_at INTEGER NOT NULL CHECK(issued_at BETWEEN 0 AND 9007199254740991),expires_at INTEGER NOT NULL CHECK(expires_at BETWEEN 0 AND 9007199254740991),retain_until INTEGER NOT NULL CHECK(retain_until BETWEEN 0 AND 9007199254740991),consumed_command TEXT) STRICT;
INSERT INTO game_metadata VALUES(1,1,0,0);
